import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../services/room_service.dart';
import '../profile/profile_screen.dart';

class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key,required this.roomId});final String roomId;@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{late final RoomService _rooms;bool _busy=false;String? _code;bool _owner=false;bool _partnerConnected=false;
 @override void initState(){super.initState();_rooms=RoomService(Supabase.instance.client);_loadConnection();}
 Future<void> _loadConnection() async{try{final r=await _rooms.roomSnapshot(widget.roomId);final members=(r['members'] as List?)??const[];final uid=Supabase.instance.client.auth.currentUser?.id;final me=members.where((m)=>m['user_id']==uid).toList();if(mounted)setState((){_owner=me.isNotEmpty&&me.first['slot']==1;_partnerConnected=members.any((m)=>m['slot']==2);});}catch(_){}}
 Future<void> _generate() async{
  if(!_owner)return;
  if(_partnerConnected){
   final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Recover partner access?'),content:const Text('This creates a new one-time recovery code. When it is used, the Partner profile and history move to the new sign-in and the previous sign-in loses Love Vault access.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Create recovery code'))]));
   if(yes!=true)return;
  }
  setState(()=>_busy=true);
  try{final c=await _rooms.generatePairingCode(2);if(mounted)setState(()=>_code=c);}
  catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Could not create the partner code.')));}
  finally{if(mounted)setState(()=>_busy=false);}
 }
 Future<void> _signOut() async{final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Sign out?'),content:const Text('Your profile stays in Love Vault.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Sign out'))]));if(yes==true)await Supabase.instance.client.auth.signOut();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Settings')),body:ListView(padding:const EdgeInsets.fromLTRB(20,12,20,40),children:[Text('Love Vault settings',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:6),const Text('Manage your profile, connection and privacy. No account email is shown here.'),const SizedBox(height:24),_Section(title:'Profile & relationship',children:[ListTile(leading:const Icon(Icons.person_outline),title:const Text('Profile and anniversary'),subtitle:const Text('Name, avatar, partner nickname, couple title and date'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ProfileScreen())))]),const SizedBox(height:18),_Section(title:'Connection',children:[const ListTile(leading:Icon(Icons.link),title:Text('Connected'),subtitle:Text('This device is connected to your Love Vault profile.')),if(_owner)Padding(padding:const EdgeInsets.fromLTRB(16,8,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(_partnerConnected?'Partner recovery':'Partner connection',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:6),Text(_partnerConnected?'Create a one-time recovery code for a lost or new sign-in. The same Partner profile and history are kept.':'Create the one-time code your Partner needs for their first connection.'),const SizedBox(height:14),FilledButton.icon(onPressed:_busy?null:_generate,icon:const Icon(Icons.key_rounded),label:Text(_busy?'Creating…':(_partnerConnected?'Generate recovery code':'Generate pairing code'))),if(_code!=null)...[const SizedBox(height:14),Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFFFFF3F5),borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(_partnerConnected?'Recovery code':'Pairing code',style:Theme.of(context).textTheme.labelLarge),const SizedBox(height:8),FittedBox(fit:BoxFit.scaleDown,child:SelectableText(_code!,style:Theme.of(context).textTheme.titleLarge)),const SizedBox(height:8),const Text('Valid for 30 minutes • one use only',textAlign:TextAlign.center),const SizedBox(height:10),OutlinedButton.icon(onPressed:(){Clipboard.setData(ClipboardData(text:_code!));ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Code copied')));},icon:const Icon(Icons.copy),label:const Text('Copy code'))]))]])),if(!_owner)const ListTile(leading:Icon(Icons.verified_user_outlined),title:Text('Partner connection'),subtitle:Text('Only the Owner can create pairing and recovery codes.'))]),const SizedBox(height:18),_Section(title:'Privacy',children:const[ListTile(leading:Icon(Icons.lock_outline),title:Text('Private space for two'),subtitle:Text('Only the two connected profiles belong in Love Vault.')),ListTile(leading:Icon(Icons.visibility_outlined),title:Text('Private surprise drafts'),subtitle:Text('Drafts remain private until their creator shares them.'))]),const SizedBox(height:18),_Section(title:'Account',children:[ListTile(leading:const Icon(Icons.logout),title:const Text('Sign out'),subtitle:const Text('Sign out on this device'),onTap:_signOut)]),const SizedBox(height:18),_Section(title:'About',children:const[ListTile(leading:Icon(Icons.favorite_outline),title:Text('Love Vault'),subtitle:Text('One private shared space for two people.'))]) ]));}
class _Section extends StatelessWidget{const _Section({required this.title,required this.children});final String title;final List<Widget> children;@override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),Card(child:Column(children:children))]);}
